using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using PawPuff.Data; using PawPuff.Services; using PawPuff.Models;
namespace PawPuff.Controllers;
public class CartController(ShopDbContext db,CartService cart) : Controller {
 public IActionResult Index()=>View(cart.Get());
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Add(int productId,int quantity=1){var p=await db.Products.FindAsync(productId);if(p==null||!p.IsActive)return NotFound();var lines=cart.Get();var line=lines.FirstOrDefault(x=>x.ProductId==productId);int desired=(line?.Quantity??0)+Math.Max(1,quantity);if(desired>p.Stock){TempData["Error"]="Not enough stock available.";return RedirectToAction("Details","Products",new{id=productId});}if(line==null)lines.Add(new CartLine{ProductId=p.Id,Name=p.Name,Price=p.Price,Quantity=desired,Stock=p.Stock,ImageUrl=p.ImageUrl});else{line.Quantity=desired;line.Stock=p.Stock;}cart.Save(lines);TempData["Message"]="Added to your cart.";return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Update(int productId,int quantity){var lines=cart.Get();var line=lines.FirstOrDefault(x=>x.ProductId==productId);var p=await db.Products.FindAsync(productId);if(line!=null&&p!=null){line.Quantity=Math.Clamp(quantity,1,p.Stock);line.Stock=p.Stock;cart.Save(lines);}return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public IActionResult Remove(int productId){var lines=cart.Get();lines.RemoveAll(x=>x.ProductId==productId);cart.Save(lines);return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Checkout(){var lines=cart.Get();foreach(var l in lines){var p=await db.Products.FindAsync(l.ProductId);if(p==null||p.Stock<l.Quantity){TempData["Error"]=$"Stock changed for {l.Name}; please update your cart.";return RedirectToAction(nameof(Index));}}if(lines.Count==0)return RedirectToAction(nameof(Index));return RedirectToAction("Index","Checkout");}
}
